acesso = Table("malhas_vendedor_empresa_acesso", metadata, Column("vendedor_id",Integer,ForeignKey("malhas_vendedor.id"),primary_key=True), Column("empresa_id",Integer,ForeignKey("malhas_empresa.id"),primary_key=True), Column("active",Boolean,nullable=False))
sessao = Table("malhas_sessao", metadata, Column("id",BigInteger,primary_key=True), Column("vendedor_id",Integer,ForeignKey("malhas_vendedor.id"),nullable=False), Column("token_digest",String(64),nullable=False,unique=True), Column("refresh_digest",String(64),nullable=False,unique=True), Column("expires_at",DateTime(timezone=True),nullable=False), Column("revoked_at",DateTime(timezone=True)), Column("created_at",DateTime(timezone=True),nullable=False))
