agente_sync = Table("malhas_agente_sync_state", metadata, Column("empresa_id",Integer,ForeignKey("malhas_empresa.id"),primary_key=True), Column("recurso",String(40),primary_key=True), Column("revision",BigInteger,nullable=False), Column("content_hash",String(64),nullable=False), Column("updated_at",DateTime(timezone=True),nullable=False,server_default=func.now()))
